import json

status = 200
response = '{"city": "İzmir", "temp": 18, "rain": 70}'
if status != 200:
    print("Hava durumu alınamadı")
else:
    data = json.loads(response)
    print(f"Bugün {data['temp']} derece")
    if data["rain"] >= 50:
        print("Şemsiyeni al!")
    else:
        print("Şemsiyeye gerek yok.")
